.work-values{padding-top:65px;border-top:1px solid var(--line)}.work-values__title{font:500 25px/1.6 var(--korean-serif);margin-bottom:25px}.work-values__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:50px}.work-values__art{height:230px;position:relative;display:flex;align-items:center;justify-content:center;gap:9px}.work-values__art b{display:block;border:1px solid #817966}.work-values__art--0 b{width:40px;height:90px;transform:rotate(-12deg);background:#e5dfd322;transition:transform .7s}.work-values__art--0 b:nth-child(2){height:115px}.work-values__art--0 b:nth-child(3){height:145px}.work-values__art--0 b:nth-child(4){height:175px}.work-values article:hover .work-values__art--0 b{transform:rotate(0)}.work-values__art--1 b{position:absolute;border-radius:50%;width:160px;height:160px}.work-values__art--1 b:nth-child(2){width:105px;height:105px;transform:translate(20px,12px)}.work-values__art--1 b:nth-child(3){width:50px;height:50px;transform:translate(-17px,-22px)}.work-values__art--1 b:nth-child(4){display:none}.work-values__art--2{gap:0}.work-values__art--2 b{width:94px;height:94px;border-radius:50%;margin:-15px}.work-values__art--2 b:nth-child(4){display:none}.work-values__heading{display:flex;align-items:baseline;gap:18px;border-top:1px solid var(--line);padding-top:23px}.work-values__heading>span{font:16px var(--serif)}.work-values h3{font:500 clamp(24px,2.3vw,34px)/1.2 var(--serif)}.work-values article p{font-size:16px;margin-top:20px;max-width:300px}
@media(max-width:1023px){.work-values__grid{gap:25px}.work-values h3{font-size:25px}.work-values__art--2 b{width:75px;height:75px}}
@media(max-width:820px){.work-values__grid{grid-template-columns:1fr;gap:45px}.work-values__art{height:195px}.work-values article p{max-width:none}.work-values h3{font-size:32px}.work-values__title{font-size:22px}.work-values__art--2 b{width:105px;height:105px}}

