.zara-details{background:#e8e5dd}.zara-details__panel{display:grid;grid-template-columns:1fr 1.1fr;gap:8%;align-items:center}.zara-details__copy h3{font:500 clamp(46px,5.3vw,78px)/1.02 var(--serif);letter-spacing:-.025em;margin:25px 0}.zara-details__copy h3 em{font-weight:400}.zara-details__copy>p{font-size:16px;max-width:460px;margin-top:20px;line-height:1.9}.zara-details__copy .text-link{margin-top:20px}.zara-details__photo{height:100%;min-height:360px;max-height:560px;overflow:hidden;border-radius:6px}.zara-details__products{display:grid;grid-template-columns:1fr 1fr;gap:20px}.zara-details__products figure{background:#f6f5f0;padding:12px}.zara-details__products figure+figure{transform:translateY(30px)}.zara-details__products figure>div{aspect-ratio:3/4;overflow:hidden}.zara-details__products figure+figure .photo{filter:grayscale(1)}.zara-details__products figcaption{padding:15px 0 5px}.zara-details__products small{font-size:9px;letter-spacing:.06em}.zara-details__products h4{font-size:15px;margin:6px 0}.zara-details__products p{font-size:12px}.zara-details__flow>div{position:relative;border-top:1px solid var(--line);padding:22px 36px 22px 35px}.zara-details__flow small{position:absolute;left:0;top:25px;font:14px var(--serif)}.zara-details__flow h4{font:500 28px var(--serif)}.zara-details__flow p{font-size:13px;margin-top:6px}.zara-details__flow span{position:absolute;right:0;top:28px}.zara-details.has-horizontal .zara-details__copy>p{font-size:15px;line-height:1.8}.zara-details.has-horizontal .zara-details__copy h3{font-size:clamp(46px,4.8vw,72px)}
@media(max-width:1023px){.zara-details__panel{gap:40px}.zara-details__copy h3{font-size:50px}.zara-details__photo{min-height:390px}.zara-details__products{gap:10px}.zara-details__products figure{padding:8px}}
