.zara-overview{background:var(--stone);padding:0 30px 30px}.zara-overview__panel{background:#dedbd1;color:#383a33;border-radius:10px;padding:45px 50px 65px}.zara-overview__heading{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid #383a3355;padding-bottom:23px;margin-bottom:40px}.zara-overview__heading h2{font:500 100px/.9 var(--serif);letter-spacing:-.06em}.zara-overview__heading>span{font-size:11px;letter-spacing:.1em}.zara-overview__layout{display:grid;grid-template-columns:1.35fr 1fr;gap:75px;align-items:center}.zara-overview__image{position:relative;aspect-ratio:756/640;overflow:hidden;border-radius:6px}.zara-overview__brand{position:absolute;top:20px;left:25px;font:500 54px/1 var(--serif);letter-spacing:-.08em}.zara-overview__caption{position:absolute;left:25px;bottom:28px;background:#e4dfd4de;padding:18px 23px}.zara-overview__caption>span{font-size:10px;letter-spacing:.12em}.zara-overview__caption p{font:25px/1.65 var(--korean-serif);margin-top:12px}.zara-overview figcaption{font-size:11px;line-height:1.6;margin-top:15px}.zara-overview__copy h3{font-size:28px;line-height:1.7;margin:20px 0}.zara-overview__copy>p{font-size:16px;line-height:1.9}.zara-overview__copy dl{margin:30px 0}.zara-overview .link-row{gap:30px}.zara-overview .text-link{flex:1}
@media(max-width:1199px){.zara-overview__panel{padding:35px 30px 50px}.zara-overview__layout{gap:35px;grid-template-columns:1fr 1fr}.zara-overview__copy h3{font-size:25px}.zara-overview__image{aspect-ratio:4/5}}
@media(max-width:820px){.zara-overview{padding:0 5px 5px}.zara-overview__panel{padding:35px 20px 50px}.zara-overview__heading h2{font-size:70px}.zara-overview__heading>span{font-size:9px;max-width:110px;text-align:right}.zara-overview__layout{grid-template-columns:1fr;gap:35px}.zara-overview__image{aspect-ratio:1}.zara-overview__caption{padding:12px 16px;left:16px;bottom:16px}.zara-overview__caption p{font-size:22px}.zara-overview__copy h3{font-size:26px}}

