.zara-process{background:var(--paper)}.zara-process__cover,.zara-process__step{display:grid;grid-template-columns:1.35fr 1fr;align-items:center;gap:6%}.zara-process__collage{position:relative;height:430px}.zara-process__collage button{position:absolute;top:25%;width:58%;padding:10px;background:#fff;border:1px solid #ddd9cf;border-radius:4px;box-shadow:0 12px 40px #36343415;cursor:zoom-in;transition:transform .5s}.zara-process__collage button:first-child{left:0;transform:rotate(-12deg)}.zara-process__collage button:nth-child(2){left:20%;top:8%;z-index:1;transform:rotate(3deg)}.zara-process__collage button:nth-child(3){right:0;top:43%;transform:rotate(10deg)}.zara-process__collage button:hover,.zara-process__collage button:focus-visible{z-index:2;transform:rotate(0) scale(1.04)}.zara-process__collage span{display:block;text-align:left;font:20px var(--serif);padding:5px 5px 12px}.zara-process__collage img{width:100%}.zara-process__intro h3{font:500 clamp(55px,6vw,90px)/.95 var(--serif);margin:20px 0 25px}.zara-process__intro h3 em{font-weight:400}.zara-process__intro>p{font-size:16px;line-height:1.9}.zara-process__intro .text-link{margin-top:25px}.zara-process__material{min-width:0}.zara-process__preview{position:relative;display:block;width:100%;padding:25px;background:#e8e6df;border:0;border-radius:6px;cursor:zoom-in;overflow:hidden}.zara-process__preview img{width:100%;aspect-ratio:4/3;object-fit:contain;transition:transform .5s}.zara-process__preview:hover img{transform:scale(1.035)}.zara-process__preview>span{position:absolute;bottom:10px;right:12px;background:var(--paper);font-size:12px;padding:5px 10px}.zara-process__material-footer{display:flex;justify-content:space-between;gap:15px;align-items:center;font-size:13px;margin-top:10px}.zara-process__material-footer .text-link{font-family:var(--sans);font-size:12px;gap:20px;border:0}.zara-process__copy h3{font:500 clamp(26px,2.4vw,36px)/1.6 var(--korean-serif);margin:22px 0}.zara-process__copy>p{font-size:16px;line-height:2}.zara-process__tabs{display:flex;flex-wrap:wrap;gap:8px;margin-top:30px}.zara-process__tabs .ui-button{font-size:13px;border-radius:2px;padding:10px 14px}.zara-process__note{display:block;font-size:12px;margin-top:22px}.zara-process.has-horizontal .zara-process__preview img{max-height:calc(100svh - 320px)}.zara-process.has-horizontal .zara-process__intro>p{font-size:15px}.zara-process.has-horizontal .zara-process__collage{height:min(430px,55vh)}
.zara-process__dialog{position:fixed;inset:24px;max-width:none;max-height:none;width:calc(100% - 48px);height:calc(100dvh - 48px);margin:0;padding:0;border:0;border-radius:6px;background:var(--paper);color:var(--ink);overflow:hidden}.zara-process__dialog::backdrop{background:#242321b3}.zara-process__dialog-bar{height:72px;display:flex;align-items:center;gap:30px;padding:12px 25px;border-bottom:1px solid var(--line);font-size:14px}.zara-process__dialog-bar>a{margin-left:auto;min-height:44px;display:flex;align-items:center}.zara-process__dialog-scroll{height:calc(100% - 72px);overflow:auto;padding:25px}.zara-process__dialog-scroll img{width:100%;min-width:850px;max-width:none;height:auto}
@media(max-width:1023px){.zara-process__cover,.zara-process__step{gap:30px}.zara-process__collage{height:350px}.zara-process__preview{padding:15px}.zara-process__intro h3{font-size:64px}}
@media(max-width:820px){.zara-process__cover,.zara-process__step{grid-template-columns:1fr;gap:25px}.zara-process__collage{height:300px;max-width:520px;width:100%;margin:auto}.zara-process__intro h3{font-size:64px}.zara-process__step .zara-process__copy{order:-1}.zara-process__copy h3{font-size:26px;margin:18px 0}.zara-process__tabs{margin-top:20px}.zara-process__note{margin-top:15px}.zara-process__preview img{aspect-ratio:4/3}.zara-process__dialog{inset:8px;width:calc(100% - 16px);height:calc(100dvh - 16px)}.zara-process__dialog-bar{padding:8px 12px;gap:10px;font-size:12px}.zara-process__dialog-scroll{padding:12px}}

src/components/ui/ui.css.text:
.photo{display:block;width:100%;height:100%;overflow:hidden}
.text-link{display:inline-flex;align-items:center;justify-content:space-between;gap:36px;min-height:44px;padding:9px 0;border-bottom:1px solid currentColor;font:500 17px/1.2 var(--serif);letter-spacing:.025em}
.text-link__window{display:grid;overflow:hidden}
.text-link__window>span{grid-area:1/1;transition:transform .5s cubic-bezier(.33,1,.68,1)}
.text-link__window>span+span{transform:translateY(125%)}
.text-link:is(:hover,:focus-visible) .text-link__window>span:first-child{transform:translateY(-125%)}
.text-link:is(:hover,:focus-visible) .text-link__window>span+span{transform:translateY(0)}
.text-link__arrow{font:22px var(--sans);transition:transform .5s}
.text-link:hover .text-link__arrow{transform:translate(3px,-3px)}
.ui-button{display:inline-flex;align-items:center;justify-content:center;min-width:44px;min-height:44px;border:1px solid var(--line);background:transparent;color:inherit;padding:9px 14px;font:inherit;cursor:pointer;transition:background .25s,color .25s}
.ui-button:hover,.ui-button[aria-pressed=true]{background:var(--ink);color:var(--paper)}
.section-label{display:flex;align-items:center;gap:22px;font-size:12px;line-height:1.5;letter-spacing:.1em;margin-bottom:32px}
.section-label>span:first-child{font-family:var(--serif);font-size:16px}
.section-label::after{content:'';height:1px;width:48px;background:currentColor;opacity:.35}
@media(prefers-reduced-motion:reduce){.text-link__window>span,.text-link__arrow{transition:none}}

