@import '@fontsource-variable/eb-garamond';
@import '@fontsource-variable/eb-garamond/wght-italic.css';
@import '@fontsource-variable/noto-sans-kr';
@import '@fontsource-variable/noto-serif-kr';
@import 'lenis/dist/lenis.css';
:root{--paper:#f6f5f0;--ink:#363434;--text:#444;--stone:#98948c;--line:rgba(54,52,52,.25);--serif:'EB Garamond Variable',Georgia,serif;--sans:'Noto Sans KR Variable','Malgun Gothic',sans-serif;--korean-serif:'Noto Serif KR Variable',serif;--gutter:clamp(20px,3.3vw,48px);font-family:var(--sans);font-size:16px;line-height:1.8;color:var(--text);background:var(--paper);font-synthesis:none;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}
*{box-sizing:border-box}body{margin:0}html{scroll-padding-top:110px}body,button,input{font-family:var(--sans)}button,a{-webkit-tap-highlight-color:transparent}a{color:inherit;text-decoration:none}button{font:inherit}button:disabled{opacity:.35;cursor:default}h1,h2,h3,h4,p,figure{margin:0}h1,h2,h3,h4{font-weight:500}p{word-break:keep-all;overflow-wrap:break-word}img{display:block;max-width:100%}button{color:inherit}section,footer{scroll-margin-top:105px}a,button,summary{touch-action:manipulation}::selection{background:#bca582;color:#262521}:focus-visible{outline:2px solid currentColor;outline-offset:6px}section:focus,main:focus,footer:focus{outline:none}button:focus:not(:focus-visible){outline:none}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.skip-link{position:fixed;left:20px;top:-90px;z-index:1001;background:var(--ink);color:var(--paper);padding:12px 20px}.skip-link:focus{top:12px}.section-space{padding:130px var(--gutter)}.display{font-family:var(--serif);font-size:clamp(60px,7.25vw,104px);font-weight:500;line-height:1.02;letter-spacing:-.025em}.display em{font-weight:400}.korean-display{font-family:var(--korean-serif);font-size:clamp(24px,2.5vw,36px);line-height:1.8;letter-spacing:-.035em}.fine-print{font-size:12px;line-height:1.7;letter-spacing:.02em}.link-row{display:flex;gap:32px;flex-wrap:wrap}.paper-grain{position:relative;isolation:isolate}.paper-grain::before{content:'';position:absolute;inset:0;pointer-events:none;z-index:-1;opacity:.12;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' opacity='.45' filter='url(%23n)'/%3E%3C/svg%3E")}.section-heading{display:flex;justify-content:space-between;align-items:end;gap:40px;margin-bottom:65px}.section-heading>p{max-width:390px;font-size:16px}.project-meta{display:grid;grid-template-columns:100px 1fr;gap:20px;padding:14px 0;border-top:1px solid var(--line)}.project-meta dt{font-size:12px;letter-spacing:.06em}.project-meta dd{margin:0;font-size:14px}.horizontal-viewport{position:relative;padding:110px 0 30px}.horizontal-heading{padding:0 var(--gutter);display:flex;align-items:center;justify-content:space-between;gap:30px;margin-bottom:32px}.horizontal-heading .section-label{margin:0}.horizontal-heading h2{font:500 32px/1.1 var(--serif)}.horizontal-panel{padding:40px var(--gutter) 70px;border-bottom:1px solid var(--line)}.horizontal-controls{display:none}.has-horizontal .horizontal-viewport{height:100svh;overflow:hidden;display:flex;flex-direction:column}.has-horizontal [data-track]{display:flex;flex:1;min-height:0;will-change:transform}.has-horizontal .horizontal-panel{width:100%;flex:0 0 100%;min-height:0;border:0;padding-top:5px;padding-bottom:25px}.has-horizontal .horizontal-controls{display:flex;align-items:center;gap:14px;margin:12px var(--gutter) 0;font-size:12px;letter-spacing:.05em}.horizontal-controls [data-count]{margin-left:auto;min-width:56px}.horizontal-controls .ui-button{border:0;font-size:22px}.horizontal-meter{height:1px;flex:1;max-width:180px;background:var(--line);margin-left:20px}.horizontal-meter span{display:block;height:100%;background:currentColor;transform:scaleX(0);transform-origin:left}.horizontal-hint{font-family:var(--serif);font-size:16px}
@media(min-width:1700px){.section-space{padding-inline:max(var(--gutter),calc((100vw - 1560px)/2))}}
@media(max-width:1199px){.section-space{padding-block:100px}.section-heading{gap:30px}.horizontal-heading{align-items:start}.display{font-size:clamp(56px,7.3vw,88px)}}
@media(max-width:820px){.section-space{padding-block:76px}.display{font-size:clamp(42px,11vw,64px)}.section-heading{display:block;margin-bottom:40px}.section-heading>p{margin-top:25px}.horizontal-heading{display:block}.horizontal-heading h2{margin-top:20px}.horizontal-viewport{padding-top:76px}.horizontal-panel{padding-top:32px;padding-bottom:55px}.section-label{margin-bottom:24px}.korean-display{font-size:24px}.project-meta{grid-template-columns:75px 1fr}.horizontal-hint{display:none}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
